          "description": "温度状态环形图满值",
          "sampleValue": 100
        },
        "statusColor": {
          "type": "string",
          "description": "温度正常状态颜色",
          "sampleValue": "#ff64bb5c"
        }
      },
      "usage": {
        "label": {
          "type": "string",
          "description": "已用时长展示文本",
          "sampleValue": "已用7小时"
        },
        "value": {
          "type": "number",
          "description": "已用时长环形图当前值",
          "sampleValue": 7
        },
        "total": {
          "type": "number",
          "description": "已用时长环形图参考满值",
          "sampleValue": 12
        },
        "statusColor": {
          "type": "string",
          "description": "已用时长环形图颜色",
          "sampleValue": "#c386f0"
        }
      }
    },
    "assets": {
      "savingIcon": {
        "type": "string",
        "description": "省电模式图标素材路径",
        "sampleValue": "resources/base/media/icon_save_power.png"
      },
      "dndIcon": {
        "type": "string",
        "description": "勿扰模式图标素材路径",
        "sampleValue": "resources/base/media/moon_circle_fill.svg"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_save_power.png",
      "description": "省电图标，适合低电模式卡片中标识省电模式开关。"
    },
    {
      "src": "resources/base/media/moon_circle_fill.svg",
      "description": "月亮圆形图标，适合表示勿扰模式、夜间模式或静音场景。"
    }
  ]
}

